The kernel violates the block-barrier invariant: all threads in the block must reach the same `__syncthreads()`. With `valid == 70`, threads 0–69 reach it while threads 70–95 skip it. That is invalid synchronization, but it does not imply every device must hang; successful immediate launch checks do not establish successful execution, and a responsive host endpoint does not establish GPU progress.

Move the barrier outside the conditional. This complete example accepts `valid` from 0 through 96 and defines the empty sum as zero.

```cuda
#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>
#include <cerrno>

static void check(cudaError_t error, const char* operation) {
    if (error != cudaSuccess) {
        std::fprintf(stderr, "%s: %s\n", operation,
                     cudaGetErrorString(error));
        std::exit(EXIT_FAILURE);
    }
}

__global__ void sum_valid(const float* input, float* output, int valid) {
    __shared__ float values[96];
    const unsigned tid = threadIdx.x;

    if (tid < static_cast<unsigned>(valid)) {
        values[tid] = input[tid];
    }

    // Every thread reaches this barrier, including when valid is zero.
    __syncthreads();

    if (tid == 0) {
        float sum = 0.0f;
        for (int i = 0; i < valid; ++i) {
            sum += values[i];
        }
        *output = sum;
    }
}

int main(int argc, char** argv) {
    int valid = 70;
    if (argc > 2) {
        std::fprintf(stderr, "Usage: %s [valid: 0..96]\n", argv[0]);
        return EXIT_FAILURE;
    }
    if (argc == 2) {
        char* end = nullptr;
        errno = 0;
        const long parsed = std::strtol(argv[1], &end, 10);
        if (errno != 0 || end == argv[1] || *end != '\0' ||
            parsed < 0 || parsed > 96) {
            std::fprintf(stderr, "valid must be an integer from 0 to 96\n");
            return EXIT_FAILURE;
        }
        valid = static_cast<int>(parsed);
    }

    float input[96];
    for (int i = 0; i < 96; ++i) {
        input[i] = static_cast<float>(i + 1);
    }
    float output = -1.0f;
    float* device_input = nullptr;
    float* device_output = nullptr;
    cudaStream_t stream;
    cudaEvent_t done;

    check(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking),
          "create stream");
    check(cudaEventCreateWithFlags(&done, cudaEventDisableTiming),
          "create event");
    check(cudaMalloc(reinterpret_cast<void**>(&device_input), sizeof(input)),
          "allocate input");
    check(cudaMalloc(reinterpret_cast<void**>(&device_output), sizeof(float)),
          "allocate output");
    check(cudaMemcpy(device_input, input, sizeof(input), cudaMemcpyHostToDevice),
          "copy input");

    sum_valid<<<1, 96, 0, stream>>>(device_input, device_output, valid);
    check(cudaGetLastError(), "launch kernel");
    check(cudaEventRecord(done, stream), "record completion");
    check(cudaEventSynchronize(done), "wait for execution");
    check(cudaMemcpy(&output, device_output, sizeof(output),
                     cudaMemcpyDeviceToHost), "copy output");

    std::printf("valid=%d sum=%g\n", valid, static_cast<double>(output));

    check(cudaFree(device_output), "free output");
    check(cudaFree(device_input), "free input");
    check(cudaEventDestroy(done), "destroy event");
    check(cudaStreamDestroy(stream), "destroy stream");
    return EXIT_SUCCESS;
}
