#!/usr/bin/env python3
import sys


def classify_root(N, edges, s, T):
    edges = list(edges)
    forward = [[] for _ in range(N)]
    reverse = [[] for _ in range(N)]
    for u, v, w in edges:
        forward[u].append(v)
        reverse[v].append(u)

    def reachable(start, graph):
        seen = [False] * N
        seen[start] = True
        stack = [start]
        while stack:
            u = stack.pop()
            for v in graph[u]:
                if not seen[v]:
                    seen[v] = True
                    stack.append(v)
        return seen

    from_s = reachable(s, forward)
    if not from_s[T]:
        return ('unreachable', None)

    to_T = reachable(T, reverse)
    relevant = [from_s[v] and to_T[v] for v in range(N)]
    k = sum(relevant)
    relevant_edges = [(u, v, w) for u, v, w in edges
                      if relevant[u] and relevant[v]]

    dist = [None] * N
    dist[s] = 0
    for round_number in range(1, k + 1):
        next_dist = dist.copy()
        changed = False
        for u, v, w in relevant_edges:
            if dist[u] is None:
                continue
            candidate = dist[u] + w
            if next_dist[v] is None or candidate < next_dist[v]:
                next_dist[v] = candidate
                changed = True
        if not changed:
            return ('finite', dist[T])
        if round_number == k:
            return ('unbounded', None)
        dist = next_dist


