Use four subgroup rounds followed by one exchange of partial sums: five float shuffles per caller. Every caller performs the final addition locally; no completed 19-input sum is broadcast.

```cuda
#include <cuda_runtime.h>

__device__ float readLane18(float value) {
    const unsigned int tid = threadIdx.x
        + blockDim.x * (threadIdx.y + blockDim.y * threadIdx.z);
    const unsigned int lane = tid & 31u;
    constexpr unsigned int mask = 0x0007ffffu;

    #pragma unroll
    for (unsigned int round = 0; round < 4; ++round) {
        const unsigned int bit = 1u << round;
        unsigned int source = lane;

        if (lane < 16u) {
            source = lane ^ bit;
        } else if (round == 0u) {
            if (lane == 16u) source = 17u;
            if (lane == 17u) source = 16u;
        } else if (round == 1u) {
            source = (lane == 18u) ? 16u : 18u;
        }

        const float other = __shfl_sync(
            mask, value, static_cast<int>(source), 32);

        if (lane < 16u) {
            value = (lane & bit)
                ? __fadd_rn(other, value)
                : __fadd_rn(value, other);
        } else if (round == 0u) {
            if (lane == 16u) value = __fadd_rn(value, other);
            if (lane == 17u) value = __fadd_rn(other, value);
        } else if (round == 1u) {
            value = (lane == 18u)
                ? __fadd_rn(other, value)
                : __fadd_rn(value, other);
        }
    }

    const unsigned int source = (lane < 16u) ? 16u : 0u;
    const float other = __shfl_sync(
        mask, value, static_cast<int>(source), 32);
    return (lane < 16u)
        ? __fadd_rn(value, other)
        : __fadd_rn(other, value);
}
